def compress(s: str) -> str:
    if not s:
        return ""
    total = sum(ord(c) for c in s)
    key = total % 101
    return ''.join(chr(ord('a') + (key % 26)) + chr(ord('a') + ((key // 26) % 26)))

def compress(s: str) -> str:
    if not s:
        return ""
    p = 31  # A prime number
    m = 10**9 + 9  # A large prime number
    hash_value = 0
    for i, char in enumerate(s):
        hash_value = (hash_value * p + (ord(char) - ord('a') + 1)) % m
    key = hash_value % 676
    return ''.join(chr(ord('a') + (key % 26)) + chr(ord('a') + ((key // 26))))

def compress(s: str) -> str:
    """Map a short lowercase token to a shorter lowercase token (used for log keys)."""
    if not s:
        return ""
    # keep first and last character; collapse the middle
    return s[0] + s[-1] if len(s) > 1 else s

